def _anchor_use_allowed(row: Dict[str, Any], use: str) -> bool:
    """锚点行是否允许指定用途：无 uses 限制（旧记录/省略）为全用途。"""
    uses = row.get("uses")
    if uses is None:
        return True
    return use in uses


class VCStore:
    """DID、凭证、演示与审计事件的多租户存储。"""

    def __init__(self, path: Optional[str] = None) -> None:
        self.path = path or DEFAULT_STORE_PATH
